#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        // suffix: p[n-y..n-1], middle: p[x..n-y-1], prefix: p[0..x-1]
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int i=0;i<n-1 && (int)ops.size()<4*n-2;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;

        if(i==0){
            // Need to bring p[j] to position 0
            // Use x=1, y=n-j if j>1 and 1+(n-j)<n => j>1
            if(j>1){
                apply_op(1, n-j); // suffix=p[j..n-1] goes to front, element at p[j] goes to pos 0
            } else {
                // j==1, use x=1,y=1 to swap first and last, then retry
                if(n>=3){
                    apply_op(1,1);
                    i--; // retry position 0
                }
            }
        } else {
            // i>0, j>i. Use x=i, y=n-j. Need i+(n-j)<n => j>i (true), need n-j>0 => j<n (true), need i>0 (true)
            apply_op(i, n-j);
            // After this, suffix p[j..n-1] is at front (positions 0..n-j-1), then middle p[i..j-1], then prefix p[0..i-1]
            // p[j] (our target) is now at position 0, but we need it at position i
            // Actually let's just re-check and place again if needed
            int nj=-1;
            for(int k=i;k<n;k++) if(p[k]==i+1){nj=k;break;}
            if(nj!=i && nj>=0){
                if(nj==i) continue;
                if(i>0 && n-nj>0 && i+(n-nj)<n)
                    apply_op(i, n-nj);
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
